import{_ as n,c as s,o as t,ag as e}from"./chunks/framework.CMajxlqO.js";const u=JSON.parse('{"title":"HMI-kommunikation med PLC","description":"","frontmatter":{},"headers":[],"relativePath":"06-kommunikation/hmi-kommunikation.md","filePath":"06-kommunikation/hmi-kommunikation.md","lastUpdated":1768470380000}'),i={name:"06-kommunikation/hmi-kommunikation.md"};function r(o,a,l,p,c,g){return t(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="hmi-kommunikation-med-plc" tabindex="-1">HMI-kommunikation med PLC <a class="header-anchor" href="#hmi-kommunikation-med-plc" aria-label="Permalink to &quot;HMI-kommunikation med PLC&quot;">​</a></h1><p>HMI (Human-Machine Interface) kommunicerar kontinuerligt med PLC:n för att visa processdata och ta emot operatörskommandon. Detta avsnitt fördjupar kommunikationsmekanismerna och optimering.</p><h2 id="kommunikationstyper" tabindex="-1">Kommunikationstyper <a class="header-anchor" href="#kommunikationstyper" aria-label="Permalink to &quot;Kommunikationstyper&quot;">​</a></h2><h3 id="_1-profinet-standard" tabindex="-1">1. Profinet (Standard) <a class="header-anchor" href="#_1-profinet-standard" aria-label="Permalink to &quot;1. Profinet (Standard)&quot;">​</a></h3><p>Mest vanlig för moderna Siemens HMI-paneler.</p><p><strong>Egenskaper:</strong></p><ul><li>📡 Ethernet-baserad (RJ45-kabel)</li><li>⚡ Snabb: 100 Mbit/s</li><li>🔄 Cyclic data exchange (kontinuerlig uppdatering)</li><li>✅ Hot-plug: HMI kan kopplas bort och återanslutas</li></ul><p><strong>Konfiguration i TIA Portal:</strong></p><ol><li>HMI → <strong>Connections</strong></li><li><strong>Add new connection</strong> → Välj PLC</li><li>Typ: <strong>HMI connection</strong></li><li>Profinet-interface väljs automatiskt</li></ol><h3 id="_2-profibus-dp" tabindex="-1">2. Profibus DP <a class="header-anchor" href="#_2-profibus-dp" aria-label="Permalink to &quot;2. Profibus DP&quot;">​</a></h3><p>Äldre HMI-paneler och äldre PLC-system.</p><p><strong>Egenskaper:</strong></p><ul><li>🔌 Seriell buss (RS-485)</li><li>🐢 Långsammare: 12 Mbit/s</li><li>📏 Max 100m (utan repeater)</li><li>⚠️ Legacy - använd endast för äldre system</li></ul><h3 id="_3-ethernet-ip-s7-communication" tabindex="-1">3. Ethernet/IP (S7-communication) <a class="header-anchor" href="#_3-ethernet-ip-s7-communication" aria-label="Permalink to &quot;3. Ethernet/IP (S7-communication)&quot;">​</a></h3><p>För icke-Profinet HMI eller SCADA-system.</p><p><strong>Egenskaper:</strong></p><ul><li>🌐 Standard TCP/IP</li><li>✅ Flexibel - kan kommunicera över WAN/Internet</li><li>⚠️ Kräver manuell konfiguration av S7-anslutning</li></ul><h2 id="datautbyte-cyclic-vs-acyclic" tabindex="-1">Datautbyte: Cyclic vs Acyclic <a class="header-anchor" href="#datautbyte-cyclic-vs-acyclic" aria-label="Permalink to &quot;Datautbyte: Cyclic vs Acyclic&quot;">​</a></h2><h3 id="cyclic-cyklisk" tabindex="-1">Cyclic (Cyklisk) <a class="header-anchor" href="#cyclic-cyklisk" aria-label="Permalink to &quot;Cyclic (Cyklisk)&quot;">​</a></h3><p>Kontinuerlig, <strong>automatisk</strong> datautbyte mellan PLC och HMI.</p><p><strong>Använd för:</strong></p><ul><li>Realtidsvärden (hastighet, tryck, temperatur)</li><li>Status-indikatorer (motor igång, larm aktiva)</li><li>Knapptryckningar</li></ul><p><strong>Exempel:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HMI läser &quot;Motor_Speed&quot; varje 100 ms</span></span>
<span class="line"><span>PLC skriver nytt värde varje 100 ms</span></span>
<span class="line"><span>→ HMI visar uppdaterad hastighet 10 gånger per sekund</span></span></code></pre></div><h3 id="acyclic-acyklisk" tabindex="-1">Acyclic (Acyklisk) <a class="header-anchor" href="#acyclic-acyklisk" aria-label="Permalink to &quot;Acyclic (Acyklisk)&quot;">​</a></h3><p><strong>På begäran</strong> - data överförs endast när HMI eller PLC begär det.</p><p><strong>Använd för:</strong></p><ul><li>Recept (endast vid laddning/sparning)</li><li>Historiska loggar (läs vid behov)</li><li>Parametrar som sällan ändras</li></ul><p><strong>Fördel:</strong> Minskar nätverksbelastning.</p><h2 id="kommunikationsoptimering" tabindex="-1">Kommunikationsoptimering <a class="header-anchor" href="#kommunikationsoptimering" aria-label="Permalink to &quot;Kommunikationsoptimering&quot;">​</a></h2><h3 id="update-cycle-uppdateringscykel" tabindex="-1">Update Cycle (Uppdateringscykel) <a class="header-anchor" href="#update-cycle-uppdateringscykel" aria-label="Permalink to &quot;Update Cycle (Uppdateringscykel)&quot;">​</a></h3><p>Hur ofta HMI läser taggar från PLC.</p><table tabindex="0"><thead><tr><th>Cykel</th><th>Användning</th><th>Nätverksbelastning</th></tr></thead><tbody><tr><td><strong>50 ms</strong></td><td>Snabba processer (motion control)</td><td>Hög</td></tr><tr><td><strong>100 ms</strong></td><td>Standard (realtidsvärden)</td><td>Medel ✅</td></tr><tr><td><strong>500 ms</strong></td><td>Långsamma processer (temperatur)</td><td>Låg</td></tr><tr><td><strong>1000 ms+</strong></td><td>Loggar, trender</td><td>Mycket låg</td></tr></tbody></table><p><strong>Ställa in update cycle:</strong></p><ol><li>HMI tags → Markera taggar</li><li><strong>Properties</strong> → <strong>Acquisition cycle</strong></li><li>Välj lämplig cykel (default: 100 ms)</li></ol><div class="tip custom-block"><p class="custom-block-title">Standard: 100 ms</p><p>För de flesta applikationer är <strong>100 ms (10 Hz)</strong> optimal balans mellan respons och nätverksbelastning.</p></div><h3 id="acquisition-mode" tabindex="-1">Acquisition Mode <a class="header-anchor" href="#acquisition-mode" aria-label="Permalink to &quot;Acquisition Mode&quot;">​</a></h3><p><strong>Hur</strong> taggar läses från PLC.</p><table tabindex="0"><thead><tr><th>Läge</th><th>Beskrivning</th><th>Användning</th></tr></thead><tbody><tr><td><strong>Cyclic continuous</strong></td><td>Läser oavsett skärm</td><td>Realtid, överallt</td></tr><tr><td><strong>Cyclic in operation</strong></td><td>Läser endast på aktiv skärm</td><td>Energibesparing</td></tr><tr><td><strong>On demand</strong></td><td>Läser endast vid begäran</td><td>Recept, sällan data</td></tr></tbody></table><p><strong>Exempel:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tag &quot;Motor_Speed&quot; → Cyclic continuous (visas på flera skärmar)</span></span>
<span class="line"><span>Tag &quot;Recipe_Name&quot; → On demand (läses vid receptladdning)</span></span></code></pre></div><h3 id="tag-grouping-tagg-gruppering" tabindex="-1">Tag Grouping (Tagg-gruppering) <a class="header-anchor" href="#tag-grouping-tagg-gruppering" aria-label="Permalink to &quot;Tag Grouping (Tagg-gruppering)&quot;">​</a></h3><p>Gruppera taggar med <strong>samma update cycle</strong> för effektiv kommunikation.</p><p><strong>Exempel:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Grupp 1 (50 ms):  Position_X, Position_Y, Velocity</span></span>
<span class="line"><span>Grupp 2 (100 ms): Motor_Speed, Pressure, Temperature</span></span>
<span class="line"><span>Grupp 3 (500 ms): Tank_Level, Production_Count</span></span></code></pre></div><p><strong>Fördel:</strong> PLC kan packa grupperade taggar i <strong>ett</strong> meddelande istället för många små.</p><h2 id="connection-parameters" tabindex="-1">Connection Parameters <a class="header-anchor" href="#connection-parameters" aria-label="Permalink to &quot;Connection Parameters&quot;">​</a></h2><h3 id="watchdog-timer" tabindex="-1">Watchdog Timer <a class="header-anchor" href="#watchdog-timer" aria-label="Permalink to &quot;Watchdog Timer&quot;">​</a></h3><p>HMI och PLC övervakar anslutningen med <strong>watchdog</strong>.</p><ul><li>Om ingen data tas emot på X sekunder → <strong>Connection fault</strong></li><li>Standard: 10 sekunder</li></ul><p><strong>Konfigurera:</strong></p><ol><li>HMI → Connections → Din PLC-anslutning</li><li><strong>Properties</strong> → <strong>Advanced</strong></li><li><strong>Monitoring time:</strong> 10000 ms (10 s)</li></ol><div class="warning custom-block"><p class="custom-block-title">Watchdog-timeout</p><p>Om HMI visar &quot;Connection error&quot; trots aktiv nätverkskabel, <strong>öka monitoring time</strong> till 20-30 sekunder. Långsamma nätverk kan ge false positives.</p></div><h3 id="data-consistency" tabindex="-1">Data Consistency <a class="header-anchor" href="#data-consistency" aria-label="Permalink to &quot;Data Consistency&quot;">​</a></h3><p>För kritiska värden, använd <strong>data consistency</strong> för att garantera att alla bits läses samtidigt.</p><p><strong>Exempel:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Motor_Status (WORD):</span></span>
<span class="line"><span>  Bit 0: Running</span></span>
<span class="line"><span>  Bit 1: Alarm</span></span>
<span class="line"><span>  Bit 2: Warning</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>Utan consistency: Kan läsa Running=1, Alarm=0 (mellanstadium)</span></span>
<span class="line"><span>Med consistency: Läser alla bits atomärt</span></span></code></pre></div><p><strong>Aktivera:</strong></p><ol><li>PLC tags → Markera tagg → <strong>Properties</strong></li><li><strong>Access</strong> → <strong>Optimized block access: Consistent access</strong></li></ol><h2 id="kommunikationsfel-och-diagnostik" tabindex="-1">Kommunikationsfel och diagnostik <a class="header-anchor" href="#kommunikationsfel-och-diagnostik" aria-label="Permalink to &quot;Kommunikationsfel och diagnostik&quot;">​</a></h2><h3 id="vanliga-fel" tabindex="-1">Vanliga fel <a class="header-anchor" href="#vanliga-fel" aria-label="Permalink to &quot;Vanliga fel&quot;">​</a></h3><h4 id="_1-connection-timeout" tabindex="-1">1. &quot;Connection timeout&quot; <a class="header-anchor" href="#_1-connection-timeout" aria-label="Permalink to &quot;1. &quot;Connection timeout&quot;&quot;">​</a></h4><p><strong>Symptom:</strong> HMI visar &quot;No connection to PLC&quot;</p><p><strong>Orsaker:</strong></p><ul><li>Nätverkskabel lös eller skadad</li><li>Fel IP-adress på HMI eller PLC</li><li>Profinet-interface inaktiverat</li><li>Brandvägg blockerar port 102 (S7-comm)</li></ul><p><strong>Lösning:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Kontrollera grön LED på Ethernet-port (HMI och PLC)</span></span>
<span class="line"><span>2. Ping PLC från HMI (System diagnostics)</span></span>
<span class="line"><span>3. Verifiera IP-adresser i TIA Portal</span></span>
<span class="line"><span>4. Testa med direktkoppling (utan switch)</span></span></code></pre></div><h4 id="_2-tag-not-found" tabindex="-1">2. &quot;Tag not found&quot; <a class="header-anchor" href="#_2-tag-not-found" aria-label="Permalink to &quot;2. &quot;Tag not found&quot;&quot;">​</a></h4><p><strong>Symptom:</strong> HMI visar &quot;#####&quot; eller &quot;Tag error&quot;</p><p><strong>Orsaker:</strong></p><ul><li>Taggen borttagen från PLC men finns kvar i HMI</li><li>Datatyp ändrad (ex: INT → REAL)</li><li>Tagg inte inkluderad i HMI-anslutning</li></ul><p><strong>Lösning:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. HMI tags → Update connection (synkronisera med PLC)</span></span>
<span class="line"><span>2. Kontrollera att taggen finns i PLC tags</span></span>
<span class="line"><span>3. Verifiera datatyp matchar</span></span></code></pre></div><h4 id="_3-langsam-uppdatering" tabindex="-1">3. Långsam uppdatering <a class="header-anchor" href="#_3-langsam-uppdatering" aria-label="Permalink to &quot;3. Långsam uppdatering&quot;">​</a></h4><p><strong>Symptom:</strong> HMI-värden uppdateras med flera sekunders fördröjning</p><p><strong>Orsaker:</strong></p><ul><li>För många taggar med för snabb update cycle</li><li>Nätverksbelastning (andra enheter på samma subnet)</li><li>PLC överbelastad (&gt;80% CPU-användning)</li></ul><p><strong>Lösning:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Öka update cycle för icke-kritiska taggar (100→500 ms)</span></span>
<span class="line"><span>2. Använd tag grouping</span></span>
<span class="line"><span>3. Separera Profinet-nätverk (dedikerad switch)</span></span>
<span class="line"><span>4. Optimera PLC-program</span></span></code></pre></div><h3 id="diagnostik-verktyg" tabindex="-1">Diagnostik-verktyg <a class="header-anchor" href="#diagnostik-verktyg" aria-label="Permalink to &quot;Diagnostik-verktyg&quot;">​</a></h3><h4 id="hmi-system-diagnostics" tabindex="-1">HMI System Diagnostics <a class="header-anchor" href="#hmi-system-diagnostics" aria-label="Permalink to &quot;HMI System Diagnostics&quot;">​</a></h4><p><strong>Tillgång:</strong></p><ol><li>På HMI-panelen: System → Diagnostics</li><li>Eller i Runtime: Settings → Diagnostics</li></ol><p><strong>Information:</strong></p><ul><li>Connection status (online/offline)</li><li>Network statistics (packet loss, latency)</li><li>Tag update frequency</li><li>Memory usage</li></ul><h4 id="tia-portal-online-test" tabindex="-1">TIA Portal Online Test <a class="header-anchor" href="#tia-portal-online-test" aria-label="Permalink to &quot;TIA Portal Online Test&quot;">​</a></h4><p><strong>Användning:</strong></p><ol><li>Gå <strong>Online</strong> med HMI</li><li><strong>Online &amp; Diagnostics</strong> → <strong>Online access</strong></li><li>Välj <strong>Communication</strong></li><li>Se aktiva anslutningar och dataflöde</li></ol><h2 id="avancerade-funktioner" tabindex="-1">Avancerade funktioner <a class="header-anchor" href="#avancerade-funktioner" aria-label="Permalink to &quot;Avancerade funktioner&quot;">​</a></h2><h3 id="recipe-management-via-kommunikation" tabindex="-1">Recipe Management via kommunikation <a class="header-anchor" href="#recipe-management-via-kommunikation" aria-label="Permalink to &quot;Recipe Management via kommunikation&quot;">​</a></h3><p>Recept lagras i HMI och överförs till PLC vid behov.</p><p><strong>Workflow:</strong></p><ol><li>Operatör väljer recept på HMI</li><li>HMI läser receptdata från intern DB</li><li>HMI skriver värden till PLC-taggar</li><li>PLC använder värdena för produktion</li></ol><p><strong>Exempel:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Recept &quot;Produkt_A&quot;:</span></span>
<span class="line"><span>  Temperature_Setpoint: 75.0 °C</span></span>
<span class="line"><span>  Pressure_Setpoint: 5.5 bar</span></span>
<span class="line"><span>  MixTime: 120 s</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>HMI skriver till:</span></span>
<span class="line"><span>  &quot;Process_Temperature_SP&quot; := 75.0</span></span>
<span class="line"><span>  &quot;Process_Pressure_SP&quot; := 5.5</span></span>
<span class="line"><span>  &quot;Process_MixTime&quot; := 120</span></span></code></pre></div><h3 id="alarm-system" tabindex="-1">Alarm System <a class="header-anchor" href="#alarm-system" aria-label="Permalink to &quot;Alarm System&quot;">​</a></h3><p>HMI kan läsa och visa larm från PLC automatiskt.</p><p><strong>Setup:</strong></p><ol><li>I PLC: Använd <strong>Program alarms</strong> eller <strong>System diagnostics</strong></li><li>I HMI: <strong>Alarms</strong> → <strong>Configure alarm classes</strong></li><li>Koppla till PLC-anslutning</li><li>HMI hanterar automatiskt: <ul><li>Larmpresentation (lista, popup)</li><li>Kvittering</li><li>Historik</li></ul></li></ol><p><strong>Exempel PLC-larm:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// I PLC-program</span></span>
<span class="line"><span>IF &quot;Temperature&quot; &gt; 850 THEN</span></span>
<span class="line"><span>    // Trigga larm</span></span>
<span class="line"><span>    &quot;Alarm_HighTemp&quot;.SIG := TRUE;</span></span>
<span class="line"><span>END_IF;</span></span></code></pre></div><p><strong>HMI visar automatiskt:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alarm: &quot;Övertemperatur i zon 1&quot;</span></span>
<span class="line"><span>Time: 2024-01-15 14:32:15</span></span>
<span class="line"><span>Status: Active (blinkar)</span></span>
<span class="line"><span>→ Operatör kvitterar → Status: Acknowledged</span></span></code></pre></div><h3 id="data-logging" tabindex="-1">Data Logging <a class="header-anchor" href="#data-logging" aria-label="Permalink to &quot;Data Logging&quot;">​</a></h3><p>HMI kan logga PLC-data för historisk analys.</p><p><strong>Konfiguration:</strong></p><ol><li>HMI → <strong>Logs</strong></li><li><strong>Add new log</strong> → Välj taggar att logga</li><li><strong>Storage:</strong> Intern HMI-minne eller USB</li><li><strong>Trigger:</strong> Cyclic (ex: varje 1 min) eller event-driven</li></ol><p><strong>Exempel:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Log &quot;Production_Data&quot;:</span></span>
<span class="line"><span>  Interval: 60 s</span></span>
<span class="line"><span>  Tags: Production_Count, Temperature, Pressure</span></span>
<span class="line"><span>  Storage: USB stick (CSV-format)</span></span></code></pre></div><p><strong>Resultat:</strong> CSV-fil för analys i Excel/BI-verktyg.</p><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Rekommendationer</p><ol><li><strong>Profinet för nya system:</strong> Snabbt och standardiserat</li><li><strong>Update cycle 100 ms:</strong> Optimal för de flesta fall</li><li><strong>Tag grouping:</strong> Gruppera taggar med samma uppdateringsbehov</li><li><strong>Watchdog 10-20 s:</strong> Undvik false connection errors</li><li><strong>Consistent access:</strong> För kritiska multi-bit-värden (WORD, DWORD)</li><li><strong>Minimize tag count:</strong> Använd endast nödvändiga taggar i HMI</li><li><strong>Diagnostics always on:</strong> Aktivera Profinet-diagnostik</li><li><strong>Network separation:</strong> Dedikerad Profinet-nätverk för kritiska system</li><li><strong>Test connection:</strong> Använd ping och System Diagnostics regelbundet</li><li><strong>Document:</strong> Dokumentera IP-adresser, device names och update cycles</li></ol></div><h2 id="prestandaexempel" tabindex="-1">Prestandaexempel <a class="header-anchor" href="#prestandaexempel" aria-label="Permalink to &quot;Prestandaexempel&quot;">​</a></h2><h3 id="bra-setup-optimerad" tabindex="-1">Bra setup (optimerad) <a class="header-anchor" href="#bra-setup-optimerad" aria-label="Permalink to &quot;Bra setup (optimerad)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Network: Dedikerad Profinet (192.168.0.x)</span></span>
<span class="line"><span>PLC: S7-1200 (192.168.0.1)</span></span>
<span class="line"><span>HMI: KTP700 (192.168.0.10)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tags:</span></span>
<span class="line"><span>  Grupp 1 (50 ms):  10 taggar (motion control)</span></span>
<span class="line"><span>  Grupp 2 (100 ms): 50 taggar (standard process)</span></span>
<span class="line"><span>  Grupp 3 (500 ms): 30 taggar (slow values)</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>Total nätverksbelastning: ~5% (margin för störningar)</span></span>
<span class="line"><span>Respons: &lt;100 ms för knapptryckningar</span></span>
<span class="line"><span>Stabilitet: 99.9% uptime</span></span></code></pre></div><h3 id="dalig-setup-ej-optimerad" tabindex="-1">Dålig setup (ej optimerad) <a class="header-anchor" href="#dalig-setup-ej-optimerad" aria-label="Permalink to &quot;Dålig setup (ej optimerad)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Network: Delat kontorsnätverk (10.0.0.x)</span></span>
<span class="line"><span>PLC: S7-1200 (10.0.0.50)</span></span>
<span class="line"><span>HMI: KTP700 (10.0.0.75)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tags:</span></span>
<span class="line"><span>  200 taggar alla med 50 ms update cycle</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>Total nätverksbelastning: 60-80% (överbelastat)</span></span>
<span class="line"><span>Respons: 500-2000 ms fördröjning</span></span>
<span class="line"><span>Stabilitet: Frekventa connection timeouts</span></span></code></pre></div><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/products?search=hmi%20communication%20configuration" target="_blank" rel="noreferrer">Siemens: HMI Communication dokumentation (sökresultat)</a></li><li><a href="https://www.youtube.com/watch?v=FpZyD6F9PSQ" target="_blank" rel="noreferrer">Video: Optimizing HMI-PLC Communication</a></li><li><a href="https://www.youtube.com/watch?v=xT8v4WlM3bU" target="_blank" rel="noreferrer">Video: HMI Diagnostics and Troubleshooting</a></li><li><a href="./frekvensomriktare-komm.html">Nästa: Frekvensomriktare-kommunikation →</a></li></ul><hr><p><strong>Relaterat:</strong></p><ul><li><a href="./../05-taggar/koppling-plc-hmi.html">Koppling PLC↔HMI</a></li><li><a href="./profinet.html">Profinet-kommunikation</a></li><li><a href="./../07-hmi-design/skarmbilder.html">HMI-design</a></li></ul>`,122)])])}const m=n(i,[["render",r]]);export{u as __pageData,m as default};
